"$script = @'
import json
import re

transcript_path = r"C:\Users\junni\.gemini\antigravity-ide\brain\68a95daa-2bee-48bc-a42e-3efb276e4e3c\.system_generated\logs\transcript.jsonl"

file_content = {}

with open(transcript_path, 'r', encoding='utf-8') as f:
    for line in f:
        try:
            step = json.loads(line)
            if step.get("type") == "TOOL_RESPONSE":
                # Check if it has output containing 'File Path: `file:///e:/diagnostico-fallas-ml/app/dashboard/streamlit_app.py`'
                output = step.get("content", "")
                if 'File Path: `file:///e:/diagnostico-fallas-ml/app/dashboard/streamlit_app.py`' in output and 'Total Lines: 1160' in output:
                    # Extract lines
                    # The format is "<line_number>: <original_line>"
                    for l in output.split('\n'):
                        m = re.match(r'^(\d+):\s(.*)$', l)
                        if m:
                            line_num = int(m.group(1))
                            line_text = m.group(2)
                            file_content[line_num] = line_text
        except Exception as e:
            pass

if file_content:
    print(f"Recovered {len(file_content)} lines")
    with open("app/dashboard/streamlit_app_recovered.py", "w", encoding="utf-8") as f:
        for i in range(1, max(file_content.keys()) + 1):
            if i in file_content:
                f.write(file_content[i] + "\n")
            else:
                f.write("\n")
else:
    print("Could not recover")
'@
Set-Content -Path "recover.py" -Value $script -Encoding UTF8
python recover.py"
